contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 a, uint256 b) public payable {
        require(b >= a);
        uint64 n = c.number(); if (__ESBMC_reverted()) return;
        uint64 ts = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 bf = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 h = c.hash(); if (__ESBMC_reverted()) return;
        uint64 sq = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 bh = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 ov = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 sc = c.l1FeeScalar(); if (__ESBMC_reverted()) return;
        assert(
            n == 0 &&
            ts == 0 &&
            bf == 0 &&
            h == bytes32(0) &&
            sq == 0 &&
            bh == bytes32(0) &&
            ov == 0 &&
            sc == 0
        );
    }
    receive() external payable {}
}

